"use strict";(self.webpackChunk_711=self.webpackChunk_711||[]).push([[586],{586(e,n,o){o.r(n),o.d(n,{default:()=>s}),o.dn(s);var r=o(540);function s(){return r.createElement("div",{className:"markdown",dangerouslySetInnerHTML:{__html:'<h1>About 711@Ingleside Volunteers</h1>\n<p>We are a group of volunteers in Ingleside, San Francisco, and are dedicated to\nimproving our neighborhood for everyone.</p>\n<p>We saw the power of consistent effort from our first encounters cleaning up our\nstreets. Over the years, we have formed a strong, reliable community of selfless\ncontributors.</p>\n<p>In 2026, we are hoping to expand our scope to new types of community-building\nprojects. If you are interested in volunteering, please email us at:</p>\n<p><a href="mailto:711@ingleside.co"><address>711@ingleside.co</address></a></p>\n<p>Follow us on Instagram: <a href="https://instagram.com/711.ingleside">711.ingleside</a></p>\n<h2>Logo</h2>\n<p>Our name and logo comes from San Francisco&#39;s Supervisor Districts 7 and 11. The\ntwo districts are bordered by Ingleside&#39;s iconic Ocean Avenue.</p>\n<p><img\n    src="/images/favicon.svg"\n    style="width: 100%; max-height: 20vh;"\n/></p>\n<p>Through our volunteering efforts, we hope to uplift everyone in our community\nand work towards a brighter future.</p>\n'}})}}}]);
